<template>
	<div class="flex h-dvh flex-col overflow-hidden bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="flex shrink-0 items-center justify-between gap-2 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex min-w-0 items-center gap-1.5">
				<RouterLink
					:to="{ name: 'Home' }"
					class="-ml-2 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali ke Home"
					aria-label="Kembali ke Home"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<h1 class="truncate !text-xl font-semibold text-ui-ink-gray-900">Notifikasi</h1>
			</div>

			<button
				v-if="rows.some((r) => !r.read)"
				type="button"
				class="shrink-0 rounded-full px-3 py-1.5 text-xs font-medium text-primary transition hover:bg-primary/5"
				@click="markAll"
			>
				Tandai semua dibaca
			</button>
		</div>

		<!-- ============ LIST ============ -->
		<div class="app-container min-h-0 flex-1 overflow-y-auto px-4 md:px-6 pb-safe">
			<div v-if="loading && !rows.length" class="flex justify-center pt-10">
				<svg
					class="h-6 w-6 animate-spin text-primary"
					viewBox="0 0 24 24"
					fill="none"
					xmlns="http://www.w3.org/2000/svg"
				>
					<circle
						cx="12"
						cy="12"
						r="9"
						stroke="currentColor"
						stroke-width="2"
						stroke-opacity="0.25"
					/>
					<path
						d="M21 12a9 9 0 0 0-9-9"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
					/>
				</svg>
			</div>

			<pre v-else-if="error" class="whitespace-pre-wrap text-sm text-ui-ink-red-600">{{
				error
			}}</pre>

			<div v-else-if="!rows.length" class="px-6 pt-16 text-center">
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="mx-auto mb-3 h-10 w-10 text-ui-ink-gray-300"
					fill="none"
					stroke="currentColor"
					stroke-width="1.6"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9" />
					<path d="M10.3 21a1.94 1.94 0 0 0 3.4 0" />
				</svg>
				<p class="text-sm text-ui-ink-gray-500">Belum ada notifikasi.</p>
			</div>

			<!-- ====== LIST CARD ====== -->
			<div v-else class="card-grid pt-3">
				<button
					v-for="n in rows"
					:key="n.name"
					type="button"
					class="flex w-full items-start gap-3 rounded-xl border p-4 text-left shadow-sm transition"
					:class="
						n.read
							? 'border-ui-line-gray-200 bg-ui-surface'
							: 'border-primary/20 bg-primary/5'
					"
					@click="openNotif(n)"
				>
					<!-- Indikator belum dibaca -->
					<span class="mt-1.5 flex h-2 w-2 shrink-0 items-center justify-center">
						<span v-if="!n.read" class="h-2 w-2 rounded-full bg-primary" />
					</span>

					<span class="min-w-0 flex-1">
						<span
							class="block break-words text-sm"
							:class="
								n.read
									? 'font-medium text-ui-ink-gray-800'
									: 'font-semibold text-ui-ink-gray-900'
							"
						>
							{{ stripHtml(n.subject) }}
						</span>
						<span
							v-if="stripHtml(n.email_content)"
							class="mt-0.5 block whitespace-pre-line break-words text-xs text-ui-ink-gray-500 line-clamp-3"
						>
							{{ stripHtml(n.email_content) }}
						</span>
						<span class="mt-1.5 block text-[11px] text-ui-ink-gray-400">{{
							formatWhen(n.creation)
						}}</span>
					</span>

					<svg
						v-if="routeForDoc(n.document_type, n.document_name)"
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="mt-0.5 h-4 w-4 shrink-0 text-ui-ink-gray-300"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m9 18 6-6-6-6" />
					</svg>
				</button>
			</div>

			<div v-if="rows.length && hasMore" class="p-3 text-center">
				<button
					type="button"
					:disabled="loading"
					class="appearance-none text-sm font-medium text-primary disabled:opacity-50"
					@click="loadMore"
				>
					{{ loading ? 'Memuat…' : 'Muat lebih banyak' }}
				</button>
			</div>
		</div>
	</div>
</template>

<script setup>
import { onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken, session } from '../data/session'
import { useHomeMenu } from '../composables/useHomeMenu'

const DOCTYPE = 'Notification Log'
const router = useRouter()

const rows = ref([])
const start = ref(0)
const pageLength = ref(30)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

// Doctype yang notifikasinya tampil di halaman ini — hanya yang menu tujuannya
// ada di app user (composables/useHomeMenu.js). Badge lonceng di Home memakai
// daftar yang sama, jadi keduanya tidak pernah berbeda isi.
const { notifDoctypes } = useHomeMenu()

// User biasa → hanya notif miliknya (filter for_user eksplisit; scoping
// permission Notification Log dilewati untuk Administrator).
// Administrator → SEMUA notif doctype terpilih milik semua user (monitoring).
function buildFilters() {
	const filters = [['document_type', 'in', notifDoctypes.value]]
	// session.user, bukan sessionUser(): mode native (token auth) tidak punya
	// cookie user_id, jadi sessionUser() null → filter for_user='' → kosong.
	const user = session.user
	if (user !== 'Administrator') filters.push(['for_user', '=', user || ''])
	return filters
}

const list = createResource({
	url: 'frappe.client.get_list',
	makeParams() {
		return {
			doctype: DOCTYPE,
			fields: JSON.stringify([
				'name',
				'subject',
				'email_content',
				'document_type',
				'document_name',
				'read',
				'creation',
				'type',
			]),
			filters: JSON.stringify(buildFilters()),
			order_by: 'creation desc',
			limit_start: start.value,
			limit_page_length: pageLength.value,
		}
	},
	auto: false,
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === pageLength.value
		loading.value = false
	},
	onError(err) {
		error.value = err?.message || String(err)
		loading.value = false
	},
})

function reload() {
	start.value = 0
	error.value = ''
	// Menu belum siap → tunggu (watch di bawah memanggil ulang). Tidak ada doctype
	// yang boleh tampil → daftar kosong tanpa query.
	if (!notifDoctypes.value) {
		loading.value = true
		return
	}
	if (!notifDoctypes.value.length) {
		rows.value = []
		hasMore.value = false
		loading.value = false
		return
	}
	loading.value = true
	list.fetch()
}
function loadMore() {
	start.value += pageLength.value
	loading.value = true
	list.fetch()
}

// ---- Tandai dibaca ----
const markResource = createResource({
	url: 'frappe.desk.doctype.notification_log.notification_log.mark_as_read',
	auto: false,
})
const markAllResource = createResource({
	url: 'frappe.desk.doctype.notification_log.notification_log.mark_all_as_read',
	auto: false,
	onSuccess() {
		rows.value.forEach((r) => (r.read = 1))
	},
})

function markRead(n) {
	if (n.read) return
	n.read = 1 // optimistis
	markResource.submit({ docname: n.name })
}
function markAll() {
	markAllResource.submit()
}

// ---- Deep-link ke dokumen terkait ----
function routeForDoc(doctype, docname) {
	if (!docname) return null
	if (doctype === 'Data Pengajuan') {
		return { name: 'DataPengajuanDetail', params: { name: docname } }
	}
	if (doctype === 'Pengajuan Cuti') {
		return { name: 'CutiDetail', params: { name: docname } }
	}
	// Permintaan reset kata sandi tidak punya halaman detail di portal —
	// arahkan ke menu tempat pemohon menindaklanjutinya.
	if (doctype === 'Password Reset Request') {
		return { name: 'ResetPassword' }
	}
	return null
}

function openNotif(n) {
	markRead(n)
	const target = routeForDoc(n.document_type, n.document_name)
	if (target) router.push(target)
}

// ---- Util ----
// Ubah konten HTML (mis. komentar/mention dari desk yang berformat Quill) jadi
// teks bersih: buang tag, decode entity (&amp; dst), hilangkan karakter zero-width
// (BOM ﻿ dari mention), lalu rapikan spasi.
function stripHtml(s) {
	if (!s) return ''
	let text
	try {
		const doc = new DOMParser().parseFromString(String(s), 'text/html')
		text = doc.body.textContent || ''
	} catch (e) {
		text = String(s).replace(/<[^>]*>/g, '')
	}
	return text
		.replace(/[﻿​]/g, '') // zero-width / BOM
		.replace(/[ \t]+/g, ' ')
		.replace(/\n{3,}/g, '\n\n')
		.trim()
}
function formatWhen(v) {
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	const now = new Date()
	const diffMs = now - d
	const min = Math.floor(diffMs / 60000)
	if (min < 1) return 'Baru saja'
	if (min < 60) return `${min} menit lalu`
	const jam = Math.floor(min / 60)
	if (jam < 24) return `${jam} jam lalu`
	const hari = Math.floor(jam / 24)
	if (hari < 7) return `${hari} hari lalu`
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}

const csrfSiap = ref(false)
onMounted(async () => {
	await refreshCsrfToken()
	csrfSiap.value = true
	reload()
})
// Daftar doctype baru terjawab setelah menu siap (role, akses fitur, izin
// doctype) — muat ulang saat itu tiba atau berubah.
watch(notifDoctypes, () => {
	if (csrfSiap.value) reload()
})
</script>
